#!/usr/bin/env python3
"""Generate the frontend fallback definitions from the canonical authored registry.

python scripts/generate_capture_screens.py          # write
python scripts/generate_capture_screens.py --check  # verify reproducible output
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path
from generate_screen_registry_snapshot import EXPORTE, _SCREEN_DEFINITIONS

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "packages/frontend-web/src/masks/capture-screens.ts"


def render() -> str:
    chunks = [
        "// Generated by scripts/generate_capture_screens.py; edit the Python ScreenDefinition instead.",
        "import type { ScreenDefinition } from '@/components/mask-builder/schema'",
        "",
        "/** Offline/bootstrap fallbacks of the authored registry. Live definitions remain authoritative. */",
    ]
    for name, screen_id in EXPORTE.items():
        definition = dict(_SCREEN_DEFINITIONS[screen_id]())
        definition.pop("agentContract", None)
        value = json.dumps(definition, ensure_ascii=False, indent=2)
        chunks.extend([f"export const {name} = {value} satisfies ScreenDefinition", ""])
    return "\n".join(chunks)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    expected = render()
    if args.check:
        if not OUT.exists() or OUT.read_text(encoding="utf-8") != expected:
            print("Capture fallbacks are stale; run python scripts/generate_capture_screens.py")
            return 1
        print(f"Capture fallbacks current ({len(EXPORTE)} definitions)")
        return 0
    OUT.write_text(expected, encoding="utf-8", newline="\n")
    print(f"Written {OUT.relative_to(ROOT)} ({len(EXPORTE)} definitions)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
